CREATE TABLE perf_plan(id INT PRIMARY KEY,dept_id INT,score INT);
INSERT INTO perf_plan VALUES(1,10,80),(2,20,90),(3,10,70);
EXPLAIN SELECT id,score FROM perf_plan WHERE dept_id=10;

CREATE TABLE perf_index(id INT PRIMARY KEY,dept_id INT,score INT);
INSERT INTO perf_index VALUES(1,10,80),(2,20,90),(3,10,70);
CREATE INDEX ix_perf_dept ON perf_index(dept_id);
EXPLAIN SELECT id,score FROM perf_index WHERE dept_id=10;

CREATE TABLE perf_multi(id INT PRIMARY KEY,dept_id INT,score INT);
CREATE INDEX ix_dept_score ON perf_multi(dept_id,score);
EXPLAIN SELECT id FROM perf_multi WHERE dept_id=10 AND score>=80;
EXPLAIN SELECT id FROM perf_multi WHERE score>=80;

CREATE TABLE perf_dept(id INT PRIMARY KEY,active INT);
CREATE TABLE perf_worker(id INT PRIMARY KEY,dept_id INT);
INSERT INTO perf_dept VALUES(10,1),(20,0);
INSERT INTO perf_worker VALUES(1,10),(2,20);
SELECT id FROM perf_worker WHERE dept_id IN(SELECT id FROM perf_dept WHERE active=1);
SELECT w.id FROM perf_worker AS w JOIN perf_dept AS d ON w.dept_id=d.id WHERE d.active=1;

CREATE TABLE slim_books(id INT PRIMARY KEY,title VARCHAR(80)) ENGINE=InnoDB;
CREATE TABLE book_details(book_id INT PRIMARY KEY,detail TEXT,FOREIGN KEY(book_id) REFERENCES slim_books(id)) ENGINE=InnoDB;
INSERT INTO slim_books VALUES(1,'数据库练习');
SELECT b.id,b.title,d.detail FROM slim_books b LEFT JOIN book_details d ON b.id=d.book_id;

CREATE TABLE source_members(id INT PRIMARY KEY,dept_id INT);
INSERT INTO source_members VALUES(1,10),(2,10),(3,20);
CREATE TABLE dept_snapshot AS SELECT dept_id,COUNT(*) AS total FROM source_members GROUP BY dept_id;
INSERT INTO source_members VALUES(4,10);
SELECT dept_id,total FROM dept_snapshot ORDER BY dept_id;

CREATE TABLE batch_rows(id INT PRIMARY KEY,amount INT) ENGINE=InnoDB;
START TRANSACTION;
INSERT INTO batch_rows VALUES(1,10),(2,20),(3,30);
COMMIT;
SELECT COUNT(*) AS total,SUM(amount) AS amount FROM batch_rows;

CREATE TABLE maintenance_demo(id INT PRIMARY KEY,value INT) ENGINE=InnoDB;
ANALYZE TABLE maintenance_demo;
CHECK TABLE maintenance_demo;
OPTIMIZE TABLE maintenance_demo;

SHOW GLOBAL VARIABLES LIKE 'innodb_buffer_pool_size';
