SHOW GLOBAL VARIABLES LIKE 'tmp_table_size';

CREATE TABLE temp_probe(id INT PRIMARY KEY,category INT);
INSERT INTO temp_probe VALUES(1,10),(2,10),(3,20);
SHOW SESSION STATUS LIKE 'Created_tmp%';
EXPLAIN SELECT category,COUNT(*) AS total FROM temp_probe GROUP BY category;
SELECT category,COUNT(*) AS total FROM temp_probe GROUP BY category;
SHOW SESSION STATUS LIKE 'Created_tmp%';

SET SESSION max_execution_time=1000;
SELECT 1 AS probe;
SET SESSION max_execution_time=0;

